-- Passage rg9-story-details-inference-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('fed45c9d-c50c-5ea2-8a73-93f41780aaa5', 'rg9-story-details-inference-p02', (select id from public.skills where slug = 'read-g9-story-details-inference'), null,
        '9-12', $q$Deep End$q$, $q$All June my brother Teo stood at the ladder
of the town pool, one hand on the cold rail,
counting the swimmers who passed him in the deep end.
He said he was waiting for the water to warm up.
It was eighty-two degrees by the lifeguard's chalkboard.

I did not push him. I had been pushed once,
the summer I was seven, by a cousin who laughed,
and I still remember the green blur of the bottom
and the way the noise of the world switched off.

So I sat on the edge with my feet in the water
and talked about nothing: the clouds, the snack bar,
the dog that kept barking at the fence.
Every day he came down one more rung.

On the last Friday of the month he let go.
He sank to his chin, kicked hard, and came up spitting,
his eyes wide open, looking for me.
I was right where I had been all along.

He swam four strokes to the wall and held on,
breathing like he had run a mile.
Then he turned around, and without a word,
he pushed off toward the middle again.$q$, 'draft')
