  ('67fd58c4-b594-52c1-bb6b-1d2775ebbf4f', null, (select id from public.skills where slug = 'read-g9-story-details-inference'), null, 'medium',
   $q$Which evidence best shows that Jonah has learned to follow the "no rounding up" rule?$q$, $q$[{"text":"\"Jonah counted for forty minutes alone.\"","is_correct":false,"misconception_token":"too-general"},{"text":"\"Jonah saw four streaks and called them out.\"","is_correct":false,"misconception_token":"opposite-evidence"},{"text":"\"By the second hour his eyes had adjusted.\"","is_correct":false,"misconception_token":"irrelevant-detail"},{"text":"\"He recorded nine meteors and left off two he was not certain about.\"","is_correct":true}]$q$::jsonb, $q$"He recorded nine meteors and left off two he was not certain about."$q$, $q$Leaving off the uncertain meteors when no one is checking is exactly what the rule requires. Calling out four streaks happened in the first hour, before he learned the rule, and one was wrong.$q$, 'draft', 'aabf52a7-4a3e-5097-af50-5e286c452e39')
